package components

// SPIKE DEVDESK-294: throwaway code, never merged. It tries to place the
// terminal's hardware cursor (tea.View.Cursor) from the router, with a
// zero-width marker that the focused field leaves in its rendering.
//
// The marker is an APC string (ESC _ ... ESC \), which x/ansi measures as zero
// cells. It sits in front of the cursor cell and carries, hex-encoded, the two
// renderings of that cell: A, the virtual cursor drawn, and B, the cell without
// it. The field renders B after the marker. The router resolves the marker in
// the final frame:
//   - found once and inside the screen: the marker is removed, B stays (no
//     virtual cursor), and View.Cursor is set;
//   - anything else: the marker and B are replaced by A, the virtual cursor
//     the field draws today.
// So the virtual cursor is dropped only when the position is resolved.

import (
	"encoding/hex"
	"image/color"
	"strconv"
	"strings"
	"sync/atomic"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/x/ansi"
)

const (
	markerOpen  = "\x1b_dd-cursor;"
	markerClose = "\x1b\\"
)

// terminalCursor gates the whole mechanism. Off, InputView is exactly
// textinput.Model.View.
var terminalCursor atomic.Bool

// SetTerminalCursor turns the hardware cursor mechanism on or off.
func SetTerminalCursor(on bool) { terminalCursor.Store(on) }

// TerminalCursor reports whether the mechanism is on.
func TerminalCursor() bool { return terminalCursor.Load() }

// InputView renders in like in.View(). When the mechanism is on and in is
// focused, it leaves a cursor marker in front of the cursor cell.
//
// bubbles/textinput v2.2.1 keeps its scroll offset private and Cursor() counts
// runes, not cells, and ignores the offset. The column is therefore found by
// rendering the input twice (cursor drawn, cursor hidden) and comparing the two.
// Both renderings work on copies; blink state is never touched (Focus() on a
// copy would cancel the live model's blink timer through the shared context).
func InputView(in textinput.Model) string {
	if !terminalCursor.Load() || !in.Focused() {
		return in.View()
	}
	vis := in
	st := vis.Styles()
	st.Cursor.Blink = false // static mode: the cell is always drawn as a cursor
